  "projects/html-css/lab8/task2.html": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <title>\u0414\u0440\u0443\u0433\u0435 \u0437\u0430\u0432\u0434\u0430\u043d\u043d\u044f</title>\r\n    <link rel=\"stylesheet\" href=\"data/css/task2.css\">\r\n</head>\r\n<body>\r\n<ul class=\"flex-container\">\r\n    <li class=\"flex-item\"><a href=\"#\">1</a></li>\r\n    <li class=\"flex-item\"><a href=\"#\">2</a></li>\r\n    <li class=\"flex-item\"><a href=\"#\">3</a></li>\r\n    <li class=\"flex-item\"><a href=\"#\">4</a></li>\r\n    <li class=\"flex-item\"><a href=\"#\">5</a></li>\r\n    <li class=\"flex-item\"><a href=\"#\">6</a></li>\r\n</ul>\r\n<br>\r\n<ul class=\"flex-container2\">\r\n    <li class=\"flex-item2\"><a href=\"#\">1</a></li>\r\n    <li class=\"flex-item2\"><a href=\"#\">2</a></li>\r\n    <li class=\"flex-item2\"><a href=\"#\">3</a></li>\r\n    <li class=\"flex-item2\"><a href=\"#\">4</a></li>\r\n    <li class=\"flex-item2\"><a href=\"#\">5</a></li>\r\n    <li class=\"flex-item2\"><a href=\"#\">6</a></li>\r\n</ul>\r\n</body>\r\n</html>\r\n",
  "projects/html-css/lab8/task3.html": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <title>\u0422\u0440\u0435\u0442\u0454 \u0437\u0430\u0432\u0434\u0430\u043d\u043d\u044f</title>\r\n    <link rel=\"stylesheet\" href=\"data/css/task3.css\">\r\n</head>\r\n<body>\r\n<div class=\"container-1\">\r\n    <div><a href=\"#\">Home</a></div>\r\n    <div><a href=\"#\">About</a></div>\r\n    <div><a href=\"#\">Products</a></div>\r\n    <div><a href=\"#\">Contact</a></div>\r\n</div>\r\n</body>\r\n</html>",
  "projects/html-css/lab8/task4.html": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <title>\u0427\u0435\u0442\u0432\u0435\u0440\u0442\u0435 \u0437\u0430\u0432\u0434\u0430\u043d\u043d\u044f</title>\r\n    <link rel=\"stylesheet\" href=\"data/css/task4.css\">\r\n</head>\r\n<body>\r\n    <div class=\"container-1\">\r\n        <div class=\"header\">HEADER</div>\r\n        <div class=\"aside-1\">ASIDE_1</div>\r\n        <div class=\"text\">Intel Corporation, commonly known as Intel, is an American multinational corporation and technology company headquartered in Santa Clara, \r\n            California. It is the world's largest semiconductor chip manufacturer by revenue, \r\n            and is one of the developer of the x86 series of instruction sets, \r\n            the instruction sets found in most personal computers (PCs). Incorporated in Delaware, \r\n            Intel ranked No. 45 in the 2020 Fortune 500 list of the largest United States corporations by total revenue for nearly a decade, \r\n            from 2007 to 2016 fiscal years.</div>\r\n        <div class=\"aside-2\">ASIDE_2</div>\r\n        <div class=\"footer\">FOOTER</div>\r\n    </div>\r\n</body>\r\n</html>",
  "projects/html-css/lab8/task5.html": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <title>\u041f\u044f\u0442\u0435 \u0437\u0430\u0432\u0434\u0430\u043d\u043d\u044f</title>\r\n    <link rel=\"stylesheet\" href=\"data/css/task5.css\">\r\n</head>\r\n<body>\r\n    <div class=\"container-1\">\r\n        <div class=\"header\">HEADER</div>\r\n        <div class=\"aside-1\">ASIDE_1</div>\r\n        <div class=\"text\">\r\n            Intel Corporation, commonly known as Intel, is an American multinational corporation and technology company headquartered in Santa Clara, \r\n            California. It is the world's largest semiconductor chip manufacturer by revenue, \r\n            and is one of the developer of the x86 series of instruction sets, \r\n            the instruction sets found in most personal computers (PCs). Incorporated in Delaware, \r\n            Intel ranked No. 45 in the 2020 Fortune 500 list of the largest United States corporations by total revenue for nearly a decade, \r\n            from 2007 to 2016 fiscal years.\r\n        </div>\r\n        <div class=\"aside-2\">ASIDE_2</div>\r\n        <div class=\"footer\">FOOTER</div>\r\n    </div>\r\n</body>\r\n</html>",
